INSERT INTO task_review_outcomes(
    id,repo_id,review_id,reported_by,client_request_id,final_commit,
    commit_binding,summary,tests_payload,approvals_payload,payload_hash,created_at
) VALUES(
    #{id},#{repositoryId},#{reviewId},#{reportedBy},#{clientRequestId},#{finalCommit},
    #{commitBinding},#{summary},CAST(#{testsPayload} AS jsonb),
    CAST(#{approvalsPayload} AS jsonb),#{payloadHash},#{createdAt}
) ON CONFLICT(review_id,reported_by,client_request_id) DO NOTHING

mapper.select:
SELECT 
FROM task_review_outcomes outcome
JOIN accounts account ON account.id=outcome.reported_by
WHERE outcome.review_id=#{reviewId} AND outcome.reported_by=#{reportedBy}
  AND outcome.client_request_id=#{clientRequestId}

SELECT 
FROM task_review_outcomes outcome
JOIN accounts account ON account.id=outcome.reported_by
WHERE outcome.repo_id=#{repositoryId} AND outcome.review_id=#{reviewId}
ORDER BY outcome.created_at DESC,outcome.id DESC LIMIT #{limit} OFFSET #{offset}

